func (e Dag_AdmissionValidationError) Error() string {
	cause := ""
	if e.cause != nil {
		cause = fmt.Sprintf(" | caused by: %v", e.cause)
	}

	key := ""
	if e.key {
		key = "key for "
	}

	return fmt.Sprintf(
		"invalid %sDag_Admission.%s: %s%s",
		key,
		e.field,
		e.reason,
		cause)
}

var _ error = Dag_AdmissionValidationError{}

var _ interface {
	Field() string
	Reason() string
	Key() bool
	Cause() error
	ErrorName() string
} = Dag_AdmissionValidationError{}
